class stringx {
public:
    const char *chars;
    const char *c_str() const { return chars; }
    stringx &operator=(const stringx &);
};
typedef const stringx *vm_str_t;
class vm_stack {
public:
    int salloc; char *buffer; char *SP; void *my_thread;
    char *get_SP() const { return SP; }
    void move_SP(int n) { SP += n; }
    void pop(int n) { move_SP(-n); }
    bool push(const char *, int);
};
class pstring {
    unsigned short pchunk[8];
public:
    pstring(const char *s) { pack_string(s); }
    void pack_string(const char *);
};
class game_info { public: bool get_str(const pstring &, stringx &) const; };
class game { public: game_info info; game_info &get_game_info() { return info; } };
namespace script_library_class { class function { public: enum entry_t { FIRST_ENTRY }; }; }
extern stringx script_game_string;
extern stringx empty_string;
extern game *g_game_ptr;
class slf_get_game_info_str_t : public script_library_class::function {
public:
    struct parms_t { vm_str_t att; };
    virtual bool operator()(vm_stack& stack, entry_t entry);
};
bool slf_get_game_info_str_t::operator()(vm_stack& stack, entry_t entry)
{
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();


    script_game_string = empty_string;
    pstring p(parms->att->c_str());
    g_game_ptr->get_game_info().get_str(p, script_game_string);

    vm_str_t result = &script_game_string;

    if (!stack.push((char*)&result,sizeof(result)) )
      ;
    return true;
}
